import 'package:text_analysis/text_analysis.dart';

final sample = 'The Australian platypus is seemingly a hybrid of a mammal and reptilian creature.';
final textDoc = await TextDocument.analyze(sourceText: sample, analyzer: English.analyzer, nGramRange: NGramRange(1, 3));
print('Flesch Reading Ease: ${textDoc.fleschReadingEaseScore().toStringAsFixed(1)}');
